    // callbackasmAddr returns address of runtime.callbackasm
    // function adjusted by i.
    // On x86 and amd64, runtime.callbackasm is a series of CALL instructions,
    // and we want callback to arrive at
    // correspondent call instruction instead of start of
    // runtime.callbackasm.
    // On ARM64, runtime.callbackasm is a series of mov and branch instructions.
    // R12 is loaded with the callback index. Each entry is two instructions,
    // hence 8 bytes.
    uintptr_t callbackasmAddr(int i)
    {
        int entrySize = {};
        //Go switch emulation
        {
            auto condition = GOARCH;
            int conditionId = -1;
            if(condition == "386"_s) { conditionId = 0; }
            else if(condition == "amd64"_s) { conditionId = 1; }
            else if(condition == "arm64"_s) { conditionId = 2; }
            switch(conditionId)
            {
                default:
                    gocpp::panic("unsupported architecture"_s);
                    break;
                case 0:
                case 1:
                    entrySize = 5;
                    break;
                case 2:
                    // On ARM64, each entry is a MOV instruction
                    // followed by a branch instruction
                    entrySize = 8;
                    break;
            }
        }
        return abi::FuncPCABI0(callbackasm) + uintptr_t(i * entrySize);
    }

    // compileCallback converts a Go function fn into a C function pointer
    // that can be passed to Windows APIs.
    //
    // On 386, if cdecl is true, the returned C function will use the
    // cdecl calling convention; otherwise, it will use stdcall. On amd64,
    // it always uses fastcall.
    //
    //go:linkname compileCallback syscall.compileCallback
    uintptr_t compileCallback(eface fn, bool cdecl)
    {
        uintptr_t code;
        if(GOARCH != "386"_s)
        {
            // cdecl is only meaningful on 386.
            cdecl = false;
        }

        if(fn._type == nullptr || rec::Kind(gocpp::recv(fn._type)) != abi::Func)
        {
            gocpp::panic("compileCallback: expected function with one uintptr-sized result"_s);
        }
        auto ft = (functype*)(gocpp::unsafe_pointer(fn._type));

        // Check arguments and construct ABI translation.
        abiDesc abiMap = {};
        for(auto [gocpp_ignored, t] : rec::InSlice(gocpp::recv(ft)))
        {
            rec::assignArg(gocpp::recv(abiMap), t);
        }
        // The Go ABI aligns the result to the word size. src is
        // already aligned.
        abiMap.dstStackSize = alignUp(abiMap.dstStackSize, goarch::PtrSize);
        abiMap.retOffset = abiMap.dstStackSize;

        if(len(rec::OutSlice(gocpp::recv(ft))) != 1)
        {
            gocpp::panic("compileCallback: expected function with one uintptr-sized result"_s);
        }
        if(rec::OutSlice(gocpp::recv(ft))[0]->Size_ != goarch::PtrSize)
        {
            gocpp::panic("compileCallback: expected function with one uintptr-sized result"_s);
        }
        if(auto k = rec::Kind(gocpp::recv(rec::OutSlice(gocpp::recv(ft))[0])); k == abi::Float32 || k == abi::Float64)
        {
            // In cdecl and stdcall, float results are returned in
            // ST(0). In fastcall, they're returned in XMM0.
            // Either way, it's not AX.
            gocpp::panic("compileCallback: float results not supported"_s);
        }
        if(intArgRegs == 0)
        {
            // Make room for the uintptr-sized result.
            // If there are argument registers, the return value will
            // be passed in the first register.
            abiMap.dstStackSize += goarch::PtrSize;
        }

        // TODO(mknyszek): Remove dstSpill from this calculation when we no longer have
        // caller reserved spill space.
        auto frameSize = alignUp(abiMap.dstStackSize, goarch::PtrSize);
        frameSize += abiMap.dstSpill;
        if(frameSize > callbackMaxFrame)
        {
            gocpp::panic("compileCallback: function argument frame too large"_s);
        }

        // For cdecl, the callee is responsible for popping its
        // arguments from the C stack.
        uintptr_t retPop = {};
        if(cdecl)
        {
            retPop = abiMap.srcStackSize;
        }

        auto key = winCallbackKey {(funcval*)(fn.data), cdecl};

        cbsLock();

        // Check if this callback is already registered.
        if(auto [n, ok] = cbs.index[key]; ok)
        {
            cbsUnlock();
            return callbackasmAddr(n);
        }

        // Register the callback.
        if(cbs.index == nullptr)
        {
            cbs.index = gocpp::make(gocpp::Tag<gocpp::map<winCallbackKey, int>>());
        }
        auto n = cbs.n;
        if(n >= len(cbs.ctxt))
        {
            cbsUnlock();
            go_throw("too many callback functions"_s);
        }
        auto c = winCallback {key.fn, retPop, abiMap};
        cbs.ctxt[n] = c;
        cbs.index[key] = n;
        cbs.n++;

        cbsUnlock();
        return callbackasmAddr(n);
    }

    
