    // callbackWrap is called by callbackasm to invoke a registered C callback.
    void callbackWrap(callbackArgs* a)
    {
        auto c = cbs.ctxt[a->index];
        a->retPop = c.retPop;

        // Convert from C to Go ABI.
        abi::RegArgs regs = {};
        gocpp::array<unsigned char, callbackMaxFrame> frame = {};
        auto goArgs = gocpp::unsafe_pointer(gocpp::make_array_ptr(frame));
        for(auto [gocpp_ignored, part] : c.abiMap.parts)
        {
            //Go switch emulation
            {
                auto condition = part.kind;
                int conditionId = -1;
                if(condition == abiPartStack) { conditionId = 0; }
                else if(condition == abiPartReg) { conditionId = 1; }
                switch(conditionId)
                {
                    case 0:
                        memmove(add(goArgs, part.dstStackOffset), add(a->args, part.srcStackOffset), part.len);
                        break;
                    case 1:
                    {
                        auto goReg = gocpp::unsafe_pointer(& regs.Ints[part.dstRegister]);
                        memmove(goReg, add(a->args, part.srcStackOffset), part.len);
                        break;
                    }
                    default:
                        gocpp::panic("bad ABI description"_s);
                        break;
                }
            }
        }

        // TODO(mknyszek): Remove this when we no longer have
        // caller reserved spill space.
        auto frameSize = alignUp(c.abiMap.dstStackSize, goarch::PtrSize);
        frameSize += c.abiMap.dstSpill;

        // Even though this is copying back results, we can pass a nil
        // type because those results must not require write barriers.
        reflectcall(nullptr, gocpp::unsafe_pointer(c.fn), noescape(goArgs), uint32_t(c.abiMap.dstStackSize), uint32_t(c.abiMap.retOffset), uint32_t(frameSize), & regs);

        // Extract the result.
        // There's always exactly one return value, one pointer in size.
        // If it's on the stack, then we will have reserved space for it
        // at the end of the frame, otherwise it was passed in a register.
        if(c.abiMap.dstStackSize != c.abiMap.retOffset)
        {
            a->result = *(uintptr_t*)(gocpp::unsafe_pointer(& frame[c.abiMap.retOffset]));
        }
        else
        {
            int zero = {};
            // On architectures with no registers, Ints[0] would be a compile error,
            // so we use a dynamic index. These architectures will never take this
            // branch, so this won't cause a runtime panic.
            a->result = regs.Ints[zero];
        }
    }

    // syscall_syscalln calls fn with args[:n].
    // It is used to implement [syscall.SyscallN].
    // It shouldn't be used in the runtime package,
    // use [stdcall] instead.
    //
    //go:linkname syscall_syscalln syscall.syscalln
    //go:nosplit
    //go:uintptrkeepalive
    std::tuple<uintptr_t, uintptr_t, uintptr_t> syscall_syscalln(uintptr_t fn, uintptr_t n, gocpp::slice<uintptr_t> args)
    {
        uintptr_t r1;
        uintptr_t r2;
        uintptr_t err;
        if(n > uintptr_t(len(args)))
        {
            // should not be reachable from user code
            gocpp::panic("syscall: n > len(args)"_s);
        }

        // The cgocall parameters are stored in m instead of in
        // the stack because the stack can move during fn if it
        // calls back into Go.
        auto c = & getg()->m->winsyscall;
        c->Fn = fn;
        c->N = n;
        if(c->N != 0)
        {
            c->Args = uintptr_t(noescape(gocpp::unsafe_pointer(& args[0])));
        }
        auto errno = cgocall(asmstdcallAddr, gocpp::unsafe_pointer(c));
        // cgocall may reschedule us on to a different M,
        // but it copies the return values into the new M's
        // so we can read them from there.
        c = & getg()->m->winsyscall;
        return {c->R1, c->R2, uintptr_t(uint32_t(errno))};
    }

